import json
from http.server import BaseHTTPRequestHandler, HTTPServer

PORT = 8104

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def _send(self, code, body):
        payload = json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        parts = [p for p in path.split("/") if p]
        # /api/v1/catalog/products/{id}/final-price
        if len(parts) == 6 and parts[3] == "products" and parts[5] == "final-price":
            self._send(200, {
                "final_price": 10.00, "original_price": 10.00,
                "discounted_price": 10.00, "default_price": True,
                "discounted": False, "discount_percent": 0,
            })
            return
        # /api/v1/catalog/products/{id}
        if len(parts) == 5 and parts[3] == "products":
            pid = parts[4]
            virtual = pid.startswith("virt")
            self._send(200, {
                "id": pid, "sku": "SKU-" + pid, "available": True, "visible": True,
                "virtual": virtual, "shippable": (not virtual), "free": False,
            })
            return
        self._send(404, {"error": "not_found", "message": "no such product"})

if __name__ == "__main__":
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()
PYEOF
    python3 "$TMPDIR/ms04_mock.py" &
    CATALOG_MOCK_PID=$!
    # brief wait for the mock to bind
    for _ in 1 2 3 4 5 10; do
        if curl -s -o /dev/null "$CATALOG_BASE_URL/products/probe"; then break; fi
        sleep 0.3
    done
}

cleanup() {
    if [ -n "$CATALOG_MOCK_PID" ]; then
        kill "$CATALOG_MOCK_PID" 2>/dev/null
    fi
    rm -rf "$TMPDIR"
}
trap cleanup EXIT

